// ------------------------------------------------------------
// File Upload Script - DMS Upload on file select
// ------------------------------------------------------------

// STEP 1: Generate Unique Timestamp ID
if (!data.timeStampID) {
    data.timeStampID = new Date().getTime();
}

// Store root form reference for async callback
var rootForm = instance.root;

// Get auth token for DMS API
var authToken = '';
try {
    var sessionData = JSON.parse(sessionStorage.getItem('0-admin-app'));
    authToken = sessionData ? sessionData.authzData : '';
} catch(ex) { console.error('[DMS] Auth token error:', ex); }

// Get current user info for DMS folder path
var currentUserInfo = null;
try {
    var userDetailsStr = localStorage.getItem('userDetails');
    if (userDetailsStr) currentUserInfo = JSON.parse(userDetailsStr);
} catch(ex) { console.error('[DMS] User details error:', ex); }

var preferredUsername = '';
var orgId = localStorage.getItem('organizationId') || sessionStorage.getItem('organizationId') || '';
try {
    if (currentUserInfo && currentUserInfo.userDetailsDTO && currentUserInfo.userDetailsDTO.username) {
        preferredUsername = currentUserInfo.userDetailsDTO.username;
    }
} catch(ex) {}

// Build DMS folder path
var dmsFolderName = '/okm:root/' + preferredUsername + '/' + orgId + '/formio-uploads/' + data.timeStampID;

// Helper: convert base64 data URI to Blob
function base64ToBlob(dataURI) {
    var byteString = atob(dataURI.split(',')[1]);
    var ab = new ArrayBuffer(byteString.length);
    var ia = new Uint8Array(ab);
    for (var i = 0; byteString.length > i; i++) {
        ia[i] = byteString.charCodeAt(i);
    }
    return new Blob([ab]);
}

// Shared table render function
function renderTable(files) {
    var container = document.querySelector('.uploadedFilesTableContainer');
    if (!container) return;
    var html = '<table style="width:100%;border-collapse:collapse;font-size:14px;">';
    html += '<thead><tr>';
    html += '<th style="background:#f1f5f9;padding:10px 12px;text-align:left;border:1px solid #e2e8f0;font-weight:600;color:#334155;width:5%">#</th>';
    html += '<th style="background:#f1f5f9;padding:10px 12px;text-align:left;border:1px solid #e2e8f0;font-weight:600;color:#334155;width:25%">Document Type</th>';
    html += '<th style="background:#f1f5f9;padding:10px 12px;text-align:left;border:1px solid #e2e8f0;font-weight:600;color:#334155;width:30%">File Name</th>';
    html += '<th style="background:#f1f5f9;padding:10px 12px;text-align:left;border:1px solid #e2e8f0;font-weight:600;color:#334155;width:10%">File Size</th>';
    html += '<th style="background:#f1f5f9;padding:10px 12px;text-align:left;border:1px solid #e2e8f0;font-weight:600;color:#334155;width:15%">Status</th>';
    html += '<th style="background:#f1f5f9;padding:10px 12px;text-align:left;border:1px solid #e2e8f0;font-weight:600;color:#334155;width:15%">Action</th>';
    html += '</tr></thead><tbody>';
    if (!files || files.length === 0) {
        html += '<tr><td colspan="6" style="text-align:center;color:#94a3b8;padding:16px;border:1px solid #e2e8f0;">No documents uploaded yet</td></tr>';
    } else {
        for (var i = 0; files.length > i; i++) {
            var statusColor = files[i].dmsUploaded ? '#16a34a' : (files[i].dmsError ? '#ef4444' : '#f59e0b');
            var statusText = files[i].dmsUploaded ? 'Uploaded' : (files[i].dmsError ? 'Failed' : 'Uploading...');
            html += '<tr style="border:1px solid #e2e8f0;">';
            html += '<td style="padding:8px 12px;border:1px solid #e2e8f0;color:#475569;">' + (i + 1) + '</td>';
            html += '<td style="padding:8px 12px;border:1px solid #e2e8f0;color:#475569;">' + files[i].type + '</td>';
            html += '<td style="padding:8px 12px;border:1px solid #e2e8f0;color:#475569;">' + files[i].originalName + '</td>';
            html += '<td style="padding:8px 12px;border:1px solid #e2e8f0;color:#475569;">' + files[i].size + '</td>';
            html += '<td style="padding:8px 12px;border:1px solid #e2e8f0;"><span style="color:' + statusColor + ';font-weight:600;">' + statusText + '</span></td>';
            html += '<td style="padding:8px 12px;border:1px solid #e2e8f0;">';
            html += '<span class="formio-remove-btn" style="background:#ef4444;color:#fff;border:none;border-radius:4px;padding:4px 12px;cursor:pointer;font-size:12px;display:inline-block;" data-remove-index="' + i + '">Remove</span>';
            html += '</td></tr>';
        }
    }
    html += '</tbody></table>';
    container.innerHTML = html;
}

// Store renderTable globally so Remove handler can use it
window._formioRenderTable = renderTable;

// Setup Remove click handler (once)
if (!window._formioRemoveListenerBound) {
    window._formioRemoveListenerBound = true;
    document.addEventListener('click', function(e) {
        var btn = e.target;
        if (!btn || !btn.classList || !btn.classList.contains('formio-remove-btn')) return;
        var idx = parseInt(btn.getAttribute('data-remove-index'));
        var rf = window._formioRootForm;
        if (!rf) return;

        var d = rf.submission.data;
        if (!d || !d.uploadedFiles || !d.uploadedFiles.fileData) return;
        var removed = d.uploadedFiles.fileData.splice(idx, 1)[0];

        if (removed && removed.docTypeKey && d[removed.docTypeKey]) {
            delete d[removed.docTypeKey];
        }

        // Delete from DMS if file was uploaded (has uuid)
        if (removed && removed.uuid) {
            var delAuthToken = '';
            try {
                var sd = JSON.parse(sessionStorage.getItem('0-admin-app'));
                delAuthToken = sd ? sd.authzData : '';
            } catch(ex) {}
            fetch('/portal/api/v2/documents/' + removed.uuid, {
                method: 'DELETE',
                headers: {
                    'Authorization': 'Bearer ' + delAuthToken
                }
            })
            .then(function(res) {
            })
            .catch(function(err) {
            });
        }

        // Re-render table immediately
        window._formioRenderTable(d.uploadedFiles.fileData);
    });
}

// Store root form ref
window._formioRootForm = rootForm;

// Render current table state
renderTable((data.uploadedFiles && data.uploadedFiles.fileData) || []);

// STEP 2: Get Selected Document Type
var docType = data.documentType
    ? (data.documentType.label || data.documentType)
    : '';

if (!docType) {
    window.alert('Please select a Document Type first.');
    return;
}

// STEP 3: Initialize uploadedFiles
if (!data.uploadedFiles || !data.uploadedFiles.fileData) {
    data.uploadedFiles = { fileData: [] };
}

// STEP 4: Prevent Duplicate
var duplicate = false;
data.uploadedFiles.fileData.forEach(function(row) {
    if (row.docTypeKey === docType) {
        duplicate = true;
    }
});

if (duplicate) {
    window.alert(docType + ' has already been added. Remove it first to re-upload.');
    return;
}

// STEP 5: File Input
var input = document.createElement('input');
input.type = 'file';
input.accept = '.pdf';

// STEP 6: File Selected -> Upload to DMS immediately
input.onchange = function(e) {
    var file = e.target.files[0];
    if (!file) return;

    var fileSize = (file.size / 1024).toFixed(1) + ' KB';
    var originalFileName = file.name;
    var fileName = data.timeStampID + '_' + originalFileName;
    var docPath = dmsFolderName + '/' + fileName;

    var reader = new FileReader();
    reader.onload = function(readerEvent) {
        var base64Data = readerEvent.target.result;

        // Use rootForm.submission.data for LIVE data
        var liveData = rootForm.submission.data;
        if (!liveData.uploadedFiles || !liveData.uploadedFiles.fileData) {
            liveData.uploadedFiles = { fileData: [] };
        }

        // Add entry with uploading status (no base64 stored in final data)
        var fileEntry = {
            storage: 'dms',
            name: fileName,
            url: docPath,
            size: fileSize,
            type: docType,
            originalName: originalFileName,
            docTypeKey: docType,
            dmsUploaded: false,
            dmsError: false,
            uuid: '',
            dmsPath: docPath
        };

        liveData.uploadedFiles.fileData.push(fileEntry);
        liveData.documentType = '';

        // Render table immediately with 'Uploading...' status
        window._formioRenderTable(liveData.uploadedFiles.fileData);

        // Convert base64 to blob and upload to DMS
        var blob = base64ToBlob(base64Data);
        var formData = new FormData();
        formData.append('content', blob, fileName);
        formData.append('docPath', docPath);
        formData.append('encrypt', 'false');
        formData.append('compression', 'false');
        formData.append('createMissingFolders', 'true');

        fetch('/portal/api/v2/documents', {
            method: 'POST',
            headers: {
                'Authorization': 'Bearer ' + authToken
            },
            body: formData
        })
        .then(function(response) {
            if (!response.ok) {
                throw new Error('DMS upload failed: ' + response.status);
            }
            return response.json();
        })
        .then(function(dmsResponse) {

            // Update the file entry with DMS response data
            var currentData = rootForm.submission.data;
            if (currentData && currentData.uploadedFiles && currentData.uploadedFiles.fileData) {
                for (var j = 0; currentData.uploadedFiles.fileData.length > j; j++) {
                    if (currentData.uploadedFiles.fileData[j].name === fileName) {
                        currentData.uploadedFiles.fileData[j].dmsUploaded = true;
                        currentData.uploadedFiles.fileData[j].uuid = dmsResponse.uuid || '';
                        currentData.uploadedFiles.fileData[j].dmsPath = dmsResponse.path || docPath;
                        currentData.uploadedFiles.fileData[j].url = dmsResponse.path || docPath;
                        currentData.uploadedFiles.fileData[j].storageProvider = 'inbuilt';
                        break;
                    }
                }
            }

            // Store DMS path under docType key
            currentData[docType] = dmsResponse.path || docPath;

            // Re-render table with updated status
            window._formioRenderTable(currentData.uploadedFiles.fileData);
        })
        .catch(function(err) {

            // Mark as failed
            var currentData = rootForm.submission.data;
            if (currentData && currentData.uploadedFiles && currentData.uploadedFiles.fileData) {
                for (var j = 0; currentData.uploadedFiles.fileData.length > j; j++) {
                    if (currentData.uploadedFiles.fileData[j].name === fileName) {
                        currentData.uploadedFiles.fileData[j].dmsError = true;
                        break;
                    }
                }
            }

            // Re-render table with error status
            window._formioRenderTable(currentData.uploadedFiles.fileData);
            window.alert('DMS Upload failed for ' + originalFileName + '. Please remove and try again.');
        });
    };
    reader.readAsDataURL(file);
};

// STEP 7: Open File Picker
input.click();

